import pytestfrom src.decorators import function@pytest.fixturedef test_func():    return functionclass TestLog:    @pytest.mark.parametrize("filename", [None, "test.log"])    def test_success(self, capsys, filename):        result = function(2, 3)        assert result == 5        captured = capsys.readouterr()        expected_output = f"{function.__name__} выполнена\n"        if filename is not None:            expected_output += f"{function.__name__} успешно выполнена\n"        # Вывод результата функции в консоль        print("Результат функции:", result)        assert captured.out == expected_output    @pytest.mark.parametrize("filename", ["test.log"])    def test_error(self, capsys, filename):        with pytest.raises(Exception):            function("a", "b")        captured = capsys.readouterr()        expected_output = (            f"{function.__name__} завершилась с ошибкой:\n"            "TypeError: unsupported operand type(s) for +: 'str' and 'str'\n"        )        assert captured.err == expected_output